create extension if not exists pgcrypto;
create type public.location_type as enum ('home_area','room','cupboard','drawer','shelf','box','safe','bag','other');
create type public.item_status as enum ('active','loaned','missing','archived');
create table public.homes (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id) on delete cascade, name text not null check(length(name) between 1 and 100), address text, created_at timestamptz not null default now());
create table public.home_members (home_id uuid references public.homes(id) on delete cascade, user_id uuid references auth.users(id) on delete cascade, role text not null default 'member' check(role in ('owner','member')), created_at timestamptz not null default now(), primary key(home_id,user_id));
create table public.locations (id uuid primary key default gen_random_uuid(), home_id uuid not null references public.homes(id) on delete cascade, parent_location_id uuid references public.locations(id) on delete restrict, name text not null check(length(name) between 1 and 120), type public.location_type not null default 'other', qr_token uuid unique not null default gen_random_uuid(), cover_image_path text, notes text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(home_id,id));
create table public.items (id uuid primary key default gen_random_uuid(), home_id uuid not null references public.homes(id) on delete cascade, current_location_id uuid not null references public.locations(id) on delete restrict, name text not null check(length(name) between 1 and 160), category text not null default 'Other', quantity integer not null default 1 check(quantity>0), photos text[] not null default '{}', description text, value numeric(12,2) check(value is null or value>=0), purchase_date date, warranty_expiry date, receipt_path text, serial_number text, qr_token uuid unique not null default gen_random_uuid(), status public.item_status not null default 'active', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.movement_history (id uuid primary key default gen_random_uuid(), item_id uuid not null references public.items(id) on delete cascade, from_location_id uuid references public.locations(id) on delete set null, to_location_id uuid not null references public.locations(id) on delete restrict, moved_by uuid not null references auth.users(id), moved_at timestamptz not null default now(), note text);
create index locations_home_parent_idx on public.locations(home_id,parent_location_id); create index items_home_location_idx on public.items(home_id,current_location_id); create index items_search_idx on public.items using gin(to_tsvector('english',coalesce(name,'')||' '||coalesce(category,'')||' '||coalesce(description,'')||' '||coalesce(serial_number,'')));
alter table public.homes enable row level security; alter table public.home_members enable row level security; alter table public.locations enable row level security; alter table public.items enable row level security; alter table public.movement_history enable row level security;
create function public.can_access_home(target uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from homes h where h.id=target and h.owner_id=auth.uid()) or exists(select 1 from home_members m where m.home_id=target and m.user_id=auth.uid()) $$;
create policy "owners manage homes" on public.homes for all using(owner_id=auth.uid()) with check(owner_id=auth.uid());
create policy "members see memberships" on public.home_members for select using(user_id=auth.uid() or public.can_access_home(home_id)); create policy "owners manage memberships" on public.home_members for all using(exists(select 1 from homes where id=home_id and owner_id=auth.uid())) with check(exists(select 1 from homes where id=home_id and owner_id=auth.uid()));
create policy "members manage locations" on public.locations for all using(public.can_access_home(home_id)) with check(public.can_access_home(home_id)); create policy "members manage items" on public.items for all using(public.can_access_home(home_id)) with check(public.can_access_home(home_id));
create policy "members see movements" on public.movement_history for select using(exists(select 1 from items i where i.id=item_id and public.can_access_home(i.home_id))); create policy "members add movements" on public.movement_history for insert with check(moved_by=auth.uid() and exists(select 1 from items i where i.id=item_id and public.can_access_home(i.home_id)));
insert into storage.buckets(id,name,public) values('inventory','inventory',false) on conflict do nothing;
create policy "private inventory reads" on storage.objects for select using(bucket_id='inventory' and auth.uid()::text=(storage.foldername(name))[1]); create policy "private inventory uploads" on storage.objects for insert with check(bucket_id='inventory' and auth.uid()::text=(storage.foldername(name))[1]); create policy "private inventory updates" on storage.objects for update using(bucket_id='inventory' and auth.uid()::text=(storage.foldername(name))[1]); create policy "private inventory deletes" on storage.objects for delete using(bucket_id='inventory' and auth.uid()::text=(storage.foldername(name))[1]);
create function public.move_item(p_item uuid,p_destination uuid,p_note text default null) returns void language plpgsql security invoker as $$ declare old_location uuid; begin select current_location_id into old_location from items where id=p_item for update; if old_location is null then raise exception 'Item not found'; end if; update items set current_location_id=p_destination,updated_at=now() where id=p_item; insert into movement_history(item_id,from_location_id,to_location_id,moved_by,note) values(p_item,old_location,p_destination,auth.uid(),p_note); end $$;
